def observed_context(case,run):
    ids={t['node_id'] for t in run['turns']};incomplete=run.get('incomplete_turn')
    if incomplete:ids.add(incomplete['node_id'])
    evidence=[{'user_turn_index':t['user_turn_index'],'node_id':t['node_id'],'tools':[{'call':e['call'],'response':e['response']} for e in t['tool_events']]} for t in run['turns']]
    interrupted=None
    if incomplete:
        interrupted={'user_turn_index':len(run['turns'])+1,'node_id':incomplete['node_id'],'assistant_audio_available':False,'tools':[{'call':e['call'],'response':e['response']} for e in run['tool_trace'][incomplete['first_tool_event_index']:]]}
    return {'evidence_version':EVIDENCE_VERSION,'category':case['classification']['category'],'dimensions':case['evaluation']['dimensions'],'semantic_checks':[c for c in case['evaluation']['checks'] if c['method']=='semantic_judge'],'user_intents':[{'node_id':n['id'],'author_text':n['user_text']} for n in case['interaction']['nodes'] if n['id'] in ids],'reference_guidance':[{'node_id':t['node_id'],'guidance':t['assistant_text']} for t in case['reference']['turns'] if t['node_id'] in ids],'oracle_environment':case['environment'],'trusted_actor':case['model_context']['actor'],'reference_tool_evidence':[{'node_id':t['node_id'],'calls':t['calls']} for t in case['reference']['turns'] if t['node_id'] in ids],'actual_tool_evidence':evidence,'interrupted_turn':interrupted,'execution_status':run['execution'],'objective_checks':[{'check_id':r['check_id'],'passed':r['passed']} for r in run['rule_checks']],'pass_policy':case['evaluation']['pass_policy']}
